import type { MetadataRoute } from "next";

/** PWA manifest: installable app shell. Icons are generated by /pwa-icon/[size]. */
export default function manifest(): MetadataRoute.Manifest {
  return {
    name: "AirIQ: Real-Time Air Quality Intelligence",
    short_name: "AirIQ",
    description: "Live AQI, pollution maps, history, forecasts, alerts and an AI assistant, built on open air-quality data.",
    start_url: "/",
    scope: "/",
    display: "standalone",
    background_color: "#0a0e14",
    theme_color: "#0f766e",
    categories: ["weather", "health", "utilities"],
    icons: [
      { src: "/pwa-icon/192", sizes: "192x192", type: "image/png", purpose: "any" },
      { src: "/pwa-icon/512", sizes: "512x512", type: "image/png", purpose: "any" },
      { src: "/pwa-icon/maskable", sizes: "512x512", type: "image/png", purpose: "maskable" },
    ],
    shortcuts: [
      { name: "Map", url: "/map" },
      { name: "Compare cities", url: "/compare" },
      { name: "Ask AirIQ", url: "/assistant" },
    ],
  };
}
